import{_ as o,a as e,b as n,c as a,d as s,e as g,f as l}from"./chunks/bounding_box.Cyg22oTW.js";import{_ as i,C as d,o as p,c,E as u,a2 as m}from"./chunks/framework.BEADHO7-.js";const O=JSON.parse('{"title":"縁取り・影・背景で装飾する","description":"ストローク、ドロップシャドウ、背景ボックスを使った文字装飾","frontmatter":{"title":"縁取り・影・背景で装飾する","description":"ストローク、ドロップシャドウ、背景ボックスを使った文字装飾","pageClass":"feature-guide","aside":false,"head":[["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-styling.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"縁取り・影・背景で装飾する | Mug Typography Manual"}],["meta",{"property":"og:description","content":"ストローク、ドロップシャドウ、背景ボックスを使った文字装飾"}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-styling.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Online Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"縁取り・影・背景で装飾する | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"ストローク、ドロップシャドウ、背景ボックスを使った文字装飾"}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Online Manual"}]]},"headers":[],"relativePath":"features/feature-styling.md","filePath":"features/feature-styling.md"}'),h={name:"features/feature-styling.md"};function b(y,t,_,S,k,f){const r=d("FeatureHero");return p(),c("div",null,[u(r,{eyebrow:"STYLE & LEGIBILITY",title:"装飾で印象に残るデザインを",description:"縁取り（2重ストローク対応）、ぼかし・発光（Glow）、ドロップシャドウ、背景ボックスを組み合わせて、背景映像の上でもくっきり読みやすいテキストを作れます。",image:"/image/stroke_fill_over_stroke.webp","image-alt":"塗りとストロークを組み合わせた文字装飾","detail-link":"/reference/reference-global-settings#輪郭線-stroke","point-one":"2重ストローク対応","point-two":"ぼかし・発光・シャドウ","point-three":"背景ボックス"}),t[0]||(t[0]=m('<h2 id="縁取りをつける" tabindex="-1">縁取りをつける <a class="header-anchor" href="#縁取りをつける" aria-label="Permalink to &quot;縁取りをつける&quot;">​</a></h2><ol><li><strong>Page</strong> を <code>Global Settings</code> にします。</li><li><strong>Stroke</strong> 内の <strong>Width</strong> を上げて、内側の輪郭線（Inner Stroke）を表示します。</li><li><strong>Color</strong>、<strong>Join Style</strong>、<strong>Order</strong> を仕上がりに合わせて選びます。</li></ol><p><img src="'+o+'" alt="塗りをストロークより前面に描画"></p><table tabindex="0"><thead><tr><th>設定</th><th>見た目への影響</th></tr></thead><tbody><tr><td><strong>Join Style</strong></td><td>角を鋭く、丸く、面取り状に切り替える</td></tr><tr><td><strong>Miter Limit</strong></td><td>鋭い角が長く伸びすぎるのを抑える</td></tr><tr><td><strong>Order</strong></td><td>塗りとストロークのどちらを前面にするか決める</td></tr><tr><td><strong>Gap</strong></td><td>塗りとストロークの間隔を空ける</td></tr><tr><td><strong>Outer Width</strong></td><td>Inner Strokeの外側に隣接する2本目の輪郭線を追加する</td></tr><tr><td><strong>Outer Color</strong></td><td>Outer Strokeの色を指定する</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Gap</strong> を上げると、塗りとストロークの間に透明な隙間を作れます。<strong>Transparent Fill</strong> と組み合わせれば、輪郭だけの中抜き文字になります。</p></div><h2 id="_2重ストロークを使う" tabindex="-1">2重ストロークを使う <a class="header-anchor" href="#_2重ストロークを使う" aria-label="Permalink to &quot;2重ストロークを使う&quot;">​</a></h2><ol><li><strong>Width</strong> を <code>0.0</code> より大きくしてInner Strokeを表示します。</li><li><strong>Outer Width</strong> を上げて、Inner Strokeの外側に2本目の輪郭線を追加します。</li><li><strong>Color</strong> と <strong>Outer Color</strong> に異なる色を指定します。</li><li>必要に応じて <strong>Gap</strong> を上げ、文字本体と最も内側にある有効なStrokeの間を空けます。</li></ol><p>Inner Stroke と Outer Stroke は、それぞれの太さ（Width / Outer Width）を 0 より大きくすると表示されます。両方を有効にすると、Inner Stroke のすぐ外側に Outer Stroke が重なります。Inner Stroke が 0 で Outer Stroke だけを有効にした場合は、文字本体と Outer Stroke の間に Gap が入ります。</p><p>特定の文字だけ縁取りを変えたいときは、Character Settings の <strong>Use Stroke</strong> をオンにすると、文字ごとに <strong>Stroke Width</strong>、<strong>Stroke Gap</strong>、<strong>Stroke Color</strong>、<strong>Outer Stroke Width</strong>、<strong>Outer Stroke Color</strong> を個別に設定できます。</p><h2 id="文字をぼかす・発光させる-blur-glow" tabindex="-1">文字をぼかす・発光させる（Blur / Glow） <a class="header-anchor" href="#文字をぼかす・発光させる-blur-glow" aria-label="Permalink to &quot;文字をぼかす・発光させる（Blur / Glow）&quot;">​</a></h2><ol><li><strong>Page</strong> を <code>Global Settings</code> にします。</li><li><strong>Blur</strong> グループ内の <strong>Blur X</strong> / <strong>Blur Y</strong> を上げて、文字そのもの（塗り・グラデーション・テクスチャ・輪郭線）をぼかします。</li><li>発光させたい場合は <strong>Glow</strong> を上げます。ぼかした文字が明るく持ち上がり、値を上げるほど芯の部分が白に近づきます（ぼかしが <code>0.0</code> のときは効果がありません）。</li></ol><table tabindex="0"><thead><tr><th>設定</th><th>見た目</th></tr></thead><tbody><tr><td><strong>Blur X / Y</strong>（ぼかしのみ）</td><td><img src="'+e+'" alt="文字のぼかし"></td></tr><tr><td><strong>Blur X / Y ＋ Glow</strong>（発光）</td><td><img src="'+n+'" alt="文字の発光"></td></tr></tbody></table><h2 id="シャドウで奥行きや後光をつける" tabindex="-1">シャドウで奥行きや後光をつける <a class="header-anchor" href="#シャドウで奥行きや後光をつける" aria-label="Permalink to &quot;シャドウで奥行きや後光をつける&quot;">​</a></h2><ol><li><strong>Page</strong> を <code>Global Settings</code> にします。</li><li><strong>Shadow Settings</strong> 内の <strong>Draw Global Shadow</strong> をオンにします。</li><li><strong>Distance</strong> と <strong>Angle</strong> で影の距離と向きを決めます。</li><li>影を柔らかくぼかすには <strong>Blur X</strong> / <strong>Blur Y</strong> を上げ、ネオンのような後光（アウターグロー）にするには <strong>Glow</strong> を上げます（<strong>Distance</strong> を <code>0.0</code> にすると文字の真後ろで発光します）。</li></ol><table tabindex="0"><thead><tr><th>設定</th><th>見た目</th></tr></thead><tbody><tr><td><strong>通常のシャドウ</strong>（ぼかしなし）</td><td><img src="'+a+'" alt="ドロップシャドウ"></td></tr><tr><td><strong>Blur X / Y</strong>（ぼかしシャドウ）</td><td><img src="'+s+'" alt="シャドウのぼかし"></td></tr><tr><td><strong>Blur X / Y ＋ Glow</strong>（発光シャドウ）</td><td><img src="'+g+'" alt="シャドウの発光"></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>特定の文字だけ影の色を変えたいときは、Character Settings の <strong>Use Indiv Shadow Color</strong> をオンにします。Draw Global Shadow がオフのときでも、このチェックを入れた文字だけに影を付けることができます。</p></div><h2 id="背景ボックスを敷く" tabindex="-1">背景ボックスを敷く <a class="header-anchor" href="#背景ボックスを敷く" aria-label="Permalink to &quot;背景ボックスを敷く&quot;">​</a></h2><ol><li><strong>Page</strong> を <code>Global Settings</code> にします。</li><li><strong>Bounding Box Settings</strong> 内の <strong>Draw Bounding Box</strong> をオンにします。</li><li>背景を塗りつぶす場合は <strong>Fill Background</strong> をオンにし、<strong>Fill Color</strong> と <strong>Fill Opacity</strong> を設定します。</li><li><strong>Margin X</strong> / <strong>Margin Y</strong> で文字周りの余白を、<strong>Border Offset</strong> / <strong>Fill Offset</strong> で枠線や塗りの位置ずれを調整します。</li><li>枠線の有無や太さは <strong>Top / Bottom / Left / Right Edge</strong> と <strong>Border Width</strong> で調整します。</li></ol><p><img src="'+l+'" alt="背景ボックス"></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>角丸（<strong>Corner Radius</strong>）は、背景の塗りには枠線の有無にかかわらず適用されます。 一方、枠線自体に角丸が適用されるのは <strong>Top / Bottom / Left / Right のすべての Edge が ON の場合のみ</strong>で、一部の辺を OFF にすると、枠線は直角のまま描画されます。</p></div>',20))])}const G=i(h,[["render",b]]);export{O as __pageData,G as default};
